def text_of(content):
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts=[]
        for c in content:
            if isinstance(c, str):
                parts.append(c)
            elif isinstance(c, dict):
                if c.get("type") in ("text","output_text") or "text" in c:
                    parts.append(c.get("text") or "")
        return "\n".join(parts)
    if isinstance(content, dict):
        return content.get("text") or json.dumps(content, ensure_ascii=False)[:500]
    return str(content)[:500]

